const kb = $('Pick KB item').item.json;
const answer = $('Generate answer').item.json.text || '';
const reasons = [];
if (answer.length > 280) reasons.push('длиннее 280 символов');
if (!answer.toLowerCase().includes(kb.kb_keyword.toLowerCase()))
  reasons.push('нет детали «' + kb.kb_keyword + '»');
const contacts = ["администратор", "личный кабинет", "преподавател", "сотрудник", "руководител"];
if (!contacts.some(c => answer.toLowerCase().includes(c)))
  reasons.push('не указано, куда обращаться дальше');
const nums = answer.match(/\d+/g) || [];
const allowed = new Set(kb.kb_numbers);
const badNums = nums.filter(n => !allowed.has(n));
if (badNums.length) reasons.push('числа не из базы: ' + badNums.join(','));
if (/[A-Za-z]/.test(answer)) reasons.push('есть латиница');
if (/[\u4e00-\u9fff]/.test(answer)) reasons.push('есть иероглифы');
const ok = reasons.length === 0;
return { json: { output: { ok, reason: reasons.join('; ') } } };
